# ---------------------------------------------------------------------------
# Loading
# ---------------------------------------------------------------------------

_CONTRACT_RELPATH = os.path.join("receipt-schema", "evidence-contract.json")
_POLICY_CACHE_RELPATH = os.path.join(".cache", "policy.json")


def _default_plugin_root() -> str:
    """Runtime root holding receipt-schema/: $SYNAPTORY_PLUGIN_ROOT, else inferred.

    Two layouts carry this module, at different depths:
      source tree      core/lib/          -> core/           (one dir up)
      composed package <pkg>/hooks/lib/   -> <pkg>/          (two dirs up)
    Probe for the schema dir rather than assuming a fixed depth.
    """
    env_root = _host_env().plugin_root().strip()
    if env_root:
        return env_root
    here = os.path.dirname(os.path.abspath(__file__))
    parent = os.path.dirname(here)
    if os.path.isdir(os.path.join(parent, "receipt-schema")):
        return parent
    return os.path.dirname(parent)


def _apply_policy_overlay(contract: dict[str, Any]) -> dict[str, Any]:
    """Overlay the signed policy cache's receipt_schema onto the contract.

    Mirrors receipt_validator._load_policy_schema: only required_fields /
    valid_roles / valid_backends are overridable, and only when non-empty.
    Any read failure leaves the contract untouched (fail-safe).
    """
    try:
        from host_env import state_dir

        with open(os.path.join(state_dir(), _POLICY_CACHE_RELPATH), "r") as f:
            cached = json.load(f)
        schema = cached.get("payload", {}).get("receipt_schema", {})
        if not isinstance(schema, dict):
            return contract
    except (OSError, json.JSONDecodeError, KeyError, AttributeError):
        return contract
    receipt = contract.setdefault("receipt", {})
    for key in ("required_fields", "valid_roles", "valid_backends"):
        values = schema.get(key)
        if values:
            receipt[key] = list(values)
    return contract


def load_contract(plugin_root: str | None = None) -> dict[str, Any]:
    """Load the evidence contract, falling back to EMBEDDED_DEFAULTS.

    Resolution: <plugin_root>/receipt-schema/evidence-contract.json where
    plugin_root defaults to $PLUGIN_ROOT, else the plugin tree this
    module lives in. On any failure (missing file, bad JSON, wrong shape) a
    deep copy of EMBEDDED_DEFAULTS is used. The signed policy cache overlay
    is applied on top in either case.
    """
    contract: dict[str, Any] | None = None
    try:
        root = plugin_root or _default_plugin_root()
        path = os.path.join(root, _CONTRACT_RELPATH)
        with open(path, "r") as f:
            loaded = json.load(f)
        if isinstance(loaded, dict) and "contract_version" in loaded:
            contract = loaded
    except (OSError, json.JSONDecodeError, ValueError):
        contract = None
    if contract is None:
        contract = copy.deepcopy(EMBEDDED_DEFAULTS)
    return _apply_policy_overlay(contract)


# ---------------------------------------------------------------------------
# Accessors
# ---------------------------------------------------------------------------

def _canonical_role(role: str, contract: dict[str, Any]) -> str:
    """Normalize a role name: dashes, strip synaptory: prefix, apply aliases."""
    name = (role or "").strip()
    if ":" in name:
        prefix, _, rest = name.partition(":")
        if prefix != "synaptory":
            return ""
        name = rest
    name = name.replace("_", "-")
    aliases = contract.get("receipt", {}).get("role_aliases", {})
    return aliases.get(name, name)


def role_stage(role: str, contract: dict[str, Any] | None = None) -> str | None:
    """Map a role to its single v3 stage, or None for multi-stage/unknown roles."""
    contract = contract or load_contract()
    name = _canonical_role(role, contract)
    return contract.get("stages", {}).get("role_to_stage", {}).get(name)


def role_abbrev(role: str, contract: dict[str, Any] | None = None) -> str | None:
    """Map a role to its receipt-filename abbreviation (se, qe, cr, ...)."""
    contract = contract or load_contract()
    name = _canonical_role(role, contract)
    return contract.get("receipt", {}).get("role_abbrevs", {}).get(name)


def allowlist(contract: dict[str, Any] | None = None) -> frozenset[str]:
    """Replayable-command program allowlist."""
    contract = contract or load_contract()
    return frozenset(
        contract.get("verification_commands", {})
        .get("replayability", {})
        .get("allowlist", [])
    )


def forbidden_tokens(contract: dict[str, Any] | None = None) -> frozenset[str]:
    """Bare shell-control tokens that make a command unreplayable."""
    contract = contract or load_contract()
    return frozenset(
        contract.get("verification_commands", {})
        .get("replayability", {})
        .get("forbidden_tokens", [])
    )


def evidence_spec(check_id: str, contract: dict[str, Any] | None = None) -> dict[str, Any] | None:
    """Machine-readable evidence spec for a DoD check, or None if unknown."""
    contract = contract or load_contract()
    check = contract.get("dod_checks", {}).get(check_id)
    if not isinstance(check, dict):
        return None
    return check.get("evidence")


def tier_checks(tier: str, contract: dict[str, Any] | None = None) -> list[str]:
    """The TIER's static DoD checks (unknown tier → early).

    NOT the checks a given story is graded on. The conditional gates
    (`ui_acceptance`, `runtime_verified`, `no_critical_findings`,
    `integration_verified`) are promoted per story and appear in no tier list,
    so this answer is a floor, never the contract. It backed the `--tier`-only
    branch of `render_envelope`, which would have shown an agent a shorter
    check set than the gate uses; use `story_pipeline.dispatch_dod_contract`
    for anything an agent will read (#501).
    """
    contract = contract or load_contract()
    tiers = contract.get("dod_tiers", {}).get("tiers", {})
    return list(tiers.get(tier) or tiers.get("early", []))


